import{_ as t,o as a,c as o,a0 as s}from"./chunks/framework.B7o6dWmz.js";const p=JSON.parse('{"title":"What is NetonAPI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/what-is.md","filePath":"guide/what-is.md","lastUpdated":1793979958000}'),r={name:"guide/what-is.md"};function i(n,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="what-is-netonapi" tabindex="-1">What is NetonAPI <a class="header-anchor" href="#what-is-netonapi" aria-label="Permalink to &quot;What is NetonAPI&quot;">​</a></h1><p>NetonAPI is an open-source, self-hosted relay for large-model APIs. You connect the upstream accounts you buy (OpenAI, Anthropic, Google, Chinese vendors or other relays), issue your own API keys to your users and bill them per token. Users call every major model with one key; official SDKs and tools such as Claude Code only need a new base URL.</p><p>It ships with two interfaces:</p><ul><li><strong>Admin console</strong> for operators: channels, pricing, negotiated prices for key accounts, revenue / cost / margin, ledger review.</li><li><strong>Website and user console</strong> for buyers: sign-up, models and prices, API keys, usage and billing, top-up.</li></ul><p><a href="https://neton.cloud" target="_blank" rel="noreferrer">Neton Cloud</a> is a relay run on NetonAPI — sign up to see it in action.</p><h2 id="what-is-different" tabindex="-1">What is different <a class="header-anchor" href="#what-is-different" aria-label="Permalink to &quot;What is different&quot;">​</a></h2><p>Most open-source relays start from &quot;forward the request&quot; and add billing as stacked ratios on top. Running a relay as a business is about other questions: what does each model sell for, what does it cost me, did this request make money, will the discount I gave a key account lose money on some channel, and does the user&#39;s bill match the price they saw?</p><table tabindex="0"><thead><tr><th>Operator question</th><th>NetonAPI</th></tr></thead><tbody><tr><td>How is the price set?</td><td>Anchored to the official price: sale = official × markup; discounts are &quot;N% of official&quot; and follow official price changes</td></tr><tr><td>What does it cost me?</td><td>Every channel records real cost: official × discount, pulled from an upstream relay&#39;s price API, or entered per model</td></tr><tr><td>Can I sell at a loss?</td><td>Every price is checked against each channel that would serve it; below cost is refused</td></tr><tr><td>Does the bill match?</td><td>Charge = tokens × the unit price the user sees</td></tr><tr><td>What if something crashes?</td><td>Reserve then settle; crashes recover, unclear cases go to manual review, nothing is double-charged</td></tr></tbody></table><h2 id="under-the-hood" tabindex="-1">Under the hood <a class="header-anchor" href="#under-the-hood" aria-label="Permalink to &quot;Under the hood&quot;">​</a></h2><ul><li>Server compiled with Kotlin/Native into <strong>a single native executable</strong> — no JVM at runtime.</li><li>PostgreSQL only; Redis optional (shared rate limits across instances).</li><li>Two Next.js apps for the admin console and the website.</li><li>License: Apache-2.0.</li></ul><p>Next: <a href="./quick-start">Quick start</a> · <a href="./pricing">Pricing and margin</a> · <a href="./features">Features</a></p>',11)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
